<script>
import {defineAsyncComponent} from "vue";
import {warpnetService} from "@/service/service";
import {toast} from "@/lib/toast";
import {watchOrder} from "@/lib/order-worker";
import {extractYoutubeId} from "@/lib/youtube";
import {DEFAULT_REACTION} from "@/lib/emoji";
import {acceptsReplies, bridgedInstance, decodeHtmlEntities, isBridgedTweet, tweetNetwork} from "@/lib/network";
import NetworkIcon from "@/components/NetworkIcon.vue";

// USDT on TRON and TRX in sun both count in millionths.
const unitDecimals = 6;

function bigUnits(value) {
  try {
    return BigInt(value || "0");
  } catch {
    return 0n;
  }
}

export default {
  name: "Tweet",
  props: {
    tweet: {type: Object, required: true},
    autoloadVideo: {type: Boolean, default: false},
  },
  components: {
    NetworkIcon,
    ReactorsOverlay: defineAsyncComponent(() => import('./ReactorsOverlay.vue')),
    RetweetersOverlay: defineAsyncComponent(() => import('./RetweetersOverlay.vue')),
    EditTweetOverlay: defineAsyncComponent(() => import('./EditTweetOverlay.vue')),
    QuoteOverlay: defineAsyncComponent(() => import('./QuoteOverlay.vue')),
    ReportDialog: defineAsyncComponent(() => import('./ReportDialog.vue')),
    ConfirmDialog: defineAsyncComponent(() => import('./ConfirmDialog.vue')),
    YoutubeEmbed: defineAsyncComponent(() => import('./YoutubeEmbed.vue')),
    PollWidget: defineAsyncComponent(() => import('./PollWidget.vue')),
    ReactionBar: defineAsyncComponent(() => import('./ReactionBar.vue')),
  },
  data() {
    return {
      profile: {},
      showReactorsOverlay: false,
      showRetweetersOverlay: false,
      showEditOverlay: false,
      showQuoteOverlay: false,
      showDropdown: false,
      showReportDialog: false,
      showDeleteConfirm: false,
      showUnlockConfirm: false,
      unlocking: false,
      unlockPending: false,
      quote: null,
      quoting: false,
      quoteError: "",
      showRetweetMenu: false,
      quotedSourceText: '',
      quotedSourceUsername: '',
      quotedUnavailable: false,
      deleted: false,
      isOwner: false,
      bookmarked: false,
      // Resolved by loadRetweeterLabel before the header paints. It must not
      // default to "You Retweeted": that claimed every boost as the viewer's.
      label: "",
      myReaction: "",
      reactions: {},
      showReactionBar: false,
      retweeted: false,
      reactionsCount: new Map(),
      retweetsCount: new Map(),
      repliesCount: new Map(),
      viewsCount: new Map(),
      tweetImages: [],
      videoSrc: '',
      videoLoading: false,
      videoError: '',
      viewedImage: null,
      viewObserver: null,
      viewRecorded: false,
      viewInFlight: false,
      statsRetried: false,
    };
  },
  computed: {
    isBridged() {
      return isBridgedTweet(this.tweet);
    },
    network() {
      return tweetNetwork(this.tweet);
    },
    networkLabel() {
      const n = this.network;
      return n ? n.charAt(0).toUpperCase() + n.slice(1) : 'Warpnet';
    },
    instanceLabel() {
      return bridgedInstance(this.tweet && this.tweet.user_id) || this.networkLabel;
    },
    canReply() {
      return acceptsReplies(this.tweet);
    },
    isLocked() {
      return !!(this.tweet && this.tweet.price) && !this.isOwner && !this.tweet.text;
    },
    unlockMessage() {
      const author = this.tweet.username || "the author";
      if (this.quoteError) {
        return `You pay ${this.tweet.price.amount} USDT to ${author}, plus a service fee of up to 5% and a TRX network fee. The payment can't be undone.`;
      }
      return `The payment goes to ${author} and can't be undone.`;
    },
    isShortOfTokens() {
      return !!this.quote && bigUnits(this.quote.balance) < bigUnits(this.quote.total);
    },
    isShortOfTrx() {
      return !!this.quote && bigUnits(this.quote.trx) < bigUnits(this.quote.network_fee);
    },
    displayText() {
      const text = (this.tweet && this.tweet.text) || '';
      return this.isBridged ? decodeHtmlEntities(text) : text;
    },
    youtubeId() {
      if (this.hasVideo) return null;
      return extractYoutubeId(this.tweet && this.tweet.text);
    },
    hasVideo() {
      return !!(this.tweet && this.tweet.video_key);
    },
    hasPoll() {
      return !!(this.tweet && this.tweet.poll && this.tweet.poll.options && this.tweet.poll.options.length > 0);
    },
    // A video post carries its first frame as the first image key (see the
    // composer in Home.vue), so it stands in as the poster rather than being
    // shown as a separate attachment.
    videoPoster() {
      return this.hasVideo ? (this.tweetImages[0] || '') : '';
    },
    galleryImages() {
      // Slots fill in one by one as each blob arrives; empty ones are
      // placeholders for fetches still in flight.
      return this.hasVideo ? [] : this.tweetImages.filter(Boolean);
    },
    // Chips are ordered by popularity, with the emoji itself breaking ties
    // so the row doesn't reshuffle between refreshes.
    reactionChips() {
      return Object.entries(this.reactions)
        .filter(([, count]) => count > 0)
        .map(([emoji, count]) => ({emoji, count}))
        .sort((a, b) => b.count - a.count || a.emoji.localeCompare(b.emoji));
    },
  },
  methods: {
    async loadAuthor() {
      try {
        this.profile = await warpnetService.getProfile(this.tweet.user_id);
        const avatar = await warpnetService.getImage({userId: this.profile.id, key: this.profile.avatar_key});
        if (avatar) this.profile.avatar = avatar;
      } catch (err) {
        console.error(`failed to load tweet author assets [${this.tweet.id}]`, err);
      }
    },
    // The header names whoever boosted the post, and only says "You" when that
    // is actually the signed-in user. An author boosting their own post — which
    // is what a bridged self-boost looks like, retweeted_by equal to user_id —
    // used to return early and leave the "You Retweeted" default standing, so a
    // GrapheneOS boost of its own reply was shown as the viewer's retweet. A
    // failed profile lookup did the same. The name is filled in synchronously
    // from what the tweet already carries, then refined once the profile loads.
    async loadRetweeterLabel() {
      const by = this.tweet.retweeted_by;
      if (!by) return;
      const owner = warpnetService.getOwnerProfile();
      if (owner && by === owner.user_id) {
        this.label = "You Retweeted";
        return;
      }
      const known = by === this.tweet.user_id ? (this.tweet.username || by) : by;
      this.label = `${known} Retweeted`;
      try {
        const retweeter = await warpnetService.getProfile(by);
        if (retweeter && retweeter.username) this.label = `${retweeter.username} Retweeted`;
      } catch (err) {
        console.warn(`failed to load retweeter profile [${by}]`, err);
      }
    },
    async openUnlock() {
      this.showUnlockConfirm = true;
      this.quote = null;
      this.quoteError = "";
      this.quoting = true;
      try {
        this.quote = await warpnetService.quoteSponsoredTweet({tweetId: this.tweet.id, userId: this.tweet.user_id});
      } catch (err) {
        console.warn(`failed to quote tweet [${this.tweet.id}]`, err);
        this.quoteError = `Couldn't work out the network fee: ${err?.message || err}`;
      } finally {
        this.quoting = false;
      }
    },
    decimal(units) {
      const value = bigUnits(units);
      const base = 10n ** BigInt(unitDecimals);
      const frac = (value % base).toString().padStart(unitDecimals, "0").replace(/0+$/, "");
      return frac ? `${value / base}.${frac}` : `${value / base}`;
    },
    async unlock() {
      this.showUnlockConfirm = false;
      if (this.unlocking) return;
      this.unlocking = true;
      try {
        const order = await warpnetService.orderSponsoredTweet({tweetId: this.tweet.id, userId: this.tweet.user_id});
        if (!order.confirmed) {
          this.awaitConfirmation();
          return;
        }
        await this.loadSponsoredContent();
      } catch (err) {
        console.error(`failed to unlock tweet [${this.tweet.id}]`, err);
        toast.error(err?.message || "Couldn't unlock the tweet.");
      } finally {
        this.unlocking = false;
      }
    },
    async loadSponsoredContent() {
      const full = await warpnetService.getSponsoredTweet({tweetId: this.tweet.id, userId: this.tweet.user_id});
      if (!full) return;
      if (full.pending) {
        this.awaitConfirmation();
        return;
      }
      this.showSponsoredContent(full);
    },
    awaitConfirmation() {
      this.unlockPending = true;
      if (this._unwatchOrder) return;
      this._unwatchOrder = watchOrder(this.tweet.id, this.tweet.user_id, (full) => {
        this._unwatchOrder = null;
        this.unlockPending = false;
        this.showSponsoredContent(full);
      });
    },
    showSponsoredContent(full) {
      this.tweet.text = full.text;
      this.tweet.image_keys = full.image_keys || [];
      this.tweet.video_key = full.video_key;
      this.loadImages();
    },
    loadImages() {
      const imageKeys = this.tweet.image_keys || [];
      if (imageKeys.length === 0) return;
      this.tweetImages = imageKeys.map(() => '');
      imageKeys.forEach((key, i) => {
        warpnetService.getImage({userId: this.tweet.user_id, key})
            .then((img) => { if (img) this.tweetImages[i] = img; })
            .catch((err) => console.warn(`failed to load tweet image [${this.tweet.id}]`, err));
      });
    },
    async refreshInteractionState() {
      const owner = warpnetService.getOwnerProfile();
      if (!owner) {
        this.myReaction = "";
        this.retweeted = false;
        this.bookmarked = false;
        return;
      }

      // The local cache only paints the button until the node answers; it
      // must never clobber that answer, which can land first.
      const cached = await warpnetService.getReactorEmoji(this.tweet.id, owner.user_id);
      if (!this._reactionAnswered) {
        this.myReaction = cached;
      }
      this.retweeted = this.tweet.retweeted_by === owner.user_id
        || await warpnetService.hasRetweeter(this.tweet.id, owner.user_id);
      this.bookmarked = await warpnetService.hasBookmark(this.tweet.id);
    },
    gotoProfile(tweetUserId) {
      this.$router.push({
        name: "Profile",
        params: {
          id: tweetUserId,
        },
      });
    },
    async openTweetPage() {
      // A bridged author (e.g. a Fediverse user who joined the thread) may be
      // unknown to the node; resolving them through the gateway first gives
      // the tweet page a routable user record.
      if (isBridgedTweet(this.tweet)) {
        try {
          const gw = await warpnetService.getGatewaySettings();
          await warpnetService.getProfile(this.tweet.user_id, gw.node_id);
        } catch (err) {
          console.warn('Failed to resolve bridged author:', err);
        }
      }
      this.$router.push({
        name: 'Tweet',
        params: { id: this.tweet.id },
        query: {
          u: this.tweet.user_id,
          // Pass parent/root so Tweet.vue can use getReply for non-root
          // entries (replies aren't stored as standalone tweets under
          // the user's TWEETS namespace, so getTweet returns 404).
          parent: this.tweet.parent_id || '',
          root: this.tweet.root_id || '',
        },
      });
    },
    onBodyClick() {
      if (this.showDropdown || this.showRetweetMenu) {
        this.closeMenus();
        return;
      }
      this.openTweetPage();
    },
    toggleDropdown() {
      this.showDropdown = !this.showDropdown;
      this.showRetweetMenu = false;
      this.syncOutsideClose();
    },
    closeMenus() {
      this.showDropdown = false;
      this.showRetweetMenu = false;
      this.teardownOutsideClose();
    },
    // Close any open dropdown when the user clicks anywhere else on the page,
    // matching standard menu behaviour. Deferred registration keeps the
    // opening click from immediately closing the menu.
    syncOutsideClose() {
      const anyOpen = this.showDropdown || this.showRetweetMenu;
      if (anyOpen && !this._docClickHandler) {
        this._docClickHandler = () => this.closeMenus();
        setTimeout(() => {
          if (this._docClickHandler) document.addEventListener("click", this._docClickHandler);
        }, 0);
      } else if (!anyOpen) {
        this.teardownOutsideClose();
      }
    },
    teardownOutsideClose() {
      if (this._docClickHandler) {
        document.removeEventListener("click", this._docClickHandler);
        this._docClickHandler = null;
      }
    },
    // Retweet button drives a small popover that offers a plain
    // retweet vs. a quote retweet. When the user already retweeted
    // (or quoted) this tweet, clicking the button just toggles the
    // retweet off without showing the menu.
    onRetweetClick() {
      this.showDropdown = false;
      if (this.retweeted) {
        this.retweet();
        return;
      }
      this.showRetweetMenu = !this.showRetweetMenu;
      this.syncOutsideClose();
    },
    async plainRetweet() {
      this.showRetweetMenu = false;
      if (!this.retweeted) {
        await this.retweet();
      }
    },
    async toggleBookmark() {
      this.showDropdown = false;
      try {
        if (this.bookmarked) {
          await warpnetService.unbookmarkTweet(this.tweet.id);
          this.bookmarked = false;
        } else {
          await warpnetService.bookmarkTweet(this.tweet.id, this.tweet.user_id);
          this.bookmarked = true;
        }
      } catch (err) {
        console.error(`failed to toggle bookmark on [${this.tweet.id}]`, err);
        toast.error(err?.message || "Couldn't update bookmark. Please try again.");
      }
    },
    async togglePin() {
      this.showDropdown = false;
      try {
        if (this.tweet.pinned) {
          await warpnetService.unpinTweet(this.tweet.id);
          this.tweet.pinned = false;
        } else {
          await warpnetService.pinTweet(this.tweet.id);
          this.tweet.pinned = true;
        }
      } catch (err) {
        console.error(`failed to toggle pin on [${this.tweet.id}]`, err);
        toast.error(err?.message || "Couldn't update pin. Please try again.");
      }
    },
    openEdit() {
      this.showDropdown = false;
      this.showEditOverlay = true;
    },
    openQuoted() {
      if (!this.tweet.quoted_tweet_id) return;
      this.$router.push({
        name: 'Tweet',
        params: { id: this.tweet.quoted_tweet_id },
        query: { u: this.tweet.quoted_user_id || '' },
      });
    },
    // Clicking an "unavailable" quoted preview is a no-op so the user
    // doesn't get bounced to a tweet that's been edited out from
    // under them.
    onQuotedClick() {
      if (this.quotedUnavailable) return;
      this.openQuoted();
    },
    async loadQuotedSource() {
      if (!this.tweet.quoted_tweet_id || !this.tweet.quoted_user_id) return;
      try {
        const src = await warpnetService.getTweet({
          tweetId: this.tweet.quoted_tweet_id,
          userId: this.tweet.quoted_user_id,
        });
        if (!src || !src.id) {
          this.quotedUnavailable = true;
          return;
        }
        // If the source has been edited *after* this quote was
        // posted, the quote no longer reflects what the user
        // actually quoted — mark it as unavailable.
        const sourceEdited = src.updated_at
          && this.tweet.created_at
          && new Date(src.updated_at) > new Date(this.tweet.created_at);
        if (sourceEdited) {
          this.quotedUnavailable = true;
          return;
        }
        this.quotedSourceText = isBridgedTweet(src)
          ? decodeHtmlEntities(src.text || '')
          : (src.text || '');
        this.quotedSourceUsername = src.username || '';
      } catch (err) {
        console.warn('failed to load quoted source:', err);
        this.quotedUnavailable = true;
      }
    },
    openQuoteOverlay() {
      this.showDropdown = false;
      this.showRetweetMenu = false;
      this.showQuoteOverlay = true;
    },
    async onQuotePosted() {
      try {
        await this.loadTweetStats(this.tweet.id, this.tweet.user_id);
      } catch (err) {
        console.error(`failed to refresh tweet stats [${this.tweet.id}]`, err);
      }
    },
    async loadVideo() {
      if (this.videoLoading || this.videoSrc) return;
      const key = this.tweet && this.tweet.video_key;
      if (!key) return;

      this.videoError = '';
      this.videoLoading = true;
      try {
        const video = await warpnetService.getVideo({
          userId: this.tweet.user_id,
          key,
        });
        if (!video || !video.file) {
          this.videoError = "This video isn't available right now. The author's node may be offline.";
          return;
        }
        this.videoSrc = video.file;
      } catch (err) {
        console.error(`failed to load tweet video [${this.tweet.id}]`, err);
        this.videoError = 'Failed to load the video.';
      } finally {
        this.videoLoading = false;
      }
    },
    onVideoError() {
      this.videoSrc = '';
      this.videoError = 'This video cannot be played. Your system may be missing the required video codec.';
    },
    openImageView(img) {
      this.viewedImage = img;
      this._onLightboxKeyup = (e) => {
        if (e.key === "Escape") this.closeImageView();
      };
      window.addEventListener("keyup", this._onLightboxKeyup);
    },
    closeImageView() {
      this.viewedImage = null;
      if (this._onLightboxKeyup) {
        window.removeEventListener("keyup", this._onLightboxKeyup);
        this._onLightboxKeyup = null;
      }
    },
    onTweetEdited(updated) {
      if (updated && updated.text) {
        this.tweet.text = updated.text;
      }
    },
    openReport() {
      this.showDropdown = false;
      this.showReportDialog = true;
    },
    async submitReport(reason) {
      try {
        // ModerationObjectType: tweets are type 1. Replies hide the
        // Report button entirely (the moderator side has no
        // reply-fetch wiring yet), so this only ever runs for root
        // tweets.
        const profile = await warpnetService.getProfile(this.tweet.user_id);
        await warpnetService.report({
          type: 1,
          objectId: this.tweet.id,
          targetUserId: this.tweet.user_id,
          targetNodeId: profile?.node_id || '',
          reason,
        });
        toast.success("Report sent to moderators.");
      } catch (err) {
        console.error('Failed to send report:', err);
        toast.error(err?.message || "Couldn't send the report. Please try again.");
      } finally {
        this.showReportDialog = false;
      }
    },
    // deleteTweet opens the confirmation; doDelete performs the irreversible
    // delete only after the user confirms.
    deleteTweet() {
      this.showDropdown = false;
      this.showDeleteConfirm = true;
    },
    async doDelete() {
      this.showDeleteConfirm = false;
      try {
        if (!this.tweet.parent_id || this.tweet.parent_id === '') {
          await warpnetService.deleteTweet({
            userId: this.tweet.user_id,
            tweetId: this.tweet.id,
          });
        } else {
          await warpnetService.deleteReply({
            userId: this.tweet.user_id,
            parentId: this.tweet.parent_id,
            rootId: this.tweet.root_id,
            replyId: this.tweet.id,
          });
        }
        this.deleted = true;
        toast.success("Tweet deleted.");
      } catch (err) {
        console.error('Failed to delete tweet:', err);
        toast.error(err?.message || "Couldn't delete the tweet. Please try again.");
      }
    },
    replyToTweet() {
      if (!this.canReply) return;
      this.openTweetPage();
    },
    async retweet() {
      const owner = warpnetService.getOwnerProfile();
      if (!owner) return;
      const retweetObject = {
        tweetId: this.tweet.id,
        userId: this.tweet.user_id,
        username: this.tweet.username,
        text: this.tweet.text,
      }
      const alreadyRetweeted = this.retweeted
      try {
        if (!alreadyRetweeted) {
          await warpnetService.retweetTweet(retweetObject);
          await warpnetService.setRetweeter(this.tweet.id, owner.user_id, owner)
          this.tweet.retweeted_by = owner.user_id;
          this.retweeted = true;
        } else {
          await warpnetService.unretweetTweet(this.tweet.id);
          await warpnetService.deleteRetweeter(this.tweet.id, owner.user_id)
          this.tweet.retweeted_by = null;
          this.retweeted = false;
        }
      } catch (err) {
        console.error(`failed to retweet/unretweet tweet [${this.tweet.id}]`, err);
        // Roll optimistic state back to what it was before this attempt.
        this.retweeted = alreadyRetweeted;
        this.tweet.retweeted_by = alreadyRetweeted ? owner.user_id : null;
        toast.error(err?.message || "Couldn't update retweet. Please try again.");
      }
      try {
        await this.loadTweetStats(this.tweet.id, this.tweet.user_id);
      } catch (err) {
        console.error(`failed to refresh tweet stats [${this.tweet.id}]`, err);
      }
    },
    // Holding the button (or hovering it on a mouse) opens the emoji row;
    // a plain click reacts with the default heart, or takes back whatever
    // reaction is already there.
    startLongPress() {
      this.cancelLongPress();
      // Cleared here rather than on release: a hold that ends off the
      // button never produces the click this flag guards against, and a
      // stale flag would swallow the next real one.
      this._barOpenedByHold = false;
      this._longPressTimer = setTimeout(() => {
        this._longPressTimer = null;
        this._barOpenedByHold = true;
        this.showReactionBar = true;
      }, 450);
    },
    cancelLongPress() {
      if (this._longPressTimer) {
        clearTimeout(this._longPressTimer);
        this._longPressTimer = null;
      }
    },
    scheduleReactionBar() {
      // Touch devices report no hover; there the long press opens the row.
      if (!window.matchMedia || !window.matchMedia('(hover: hover)').matches) return;
      this.cancelReactionBar();
      this._hoverTimer = setTimeout(() => {
        this._hoverTimer = null;
        this.showReactionBar = true;
      }, 600);
    },
    cancelReactionBar() {
      if (this._hoverTimer) {
        clearTimeout(this._hoverTimer);
        this._hoverTimer = null;
      }
    },
    // The bar is a child of the hovered area, so moving onto it doesn't
    // count as leaving; anything else does and takes the bar with it.
    closeReactionBarOnLeave() {
      this.cancelReactionBar();
      this.showReactionBar = false;
    },
    toggleOwnReaction() {
      this.cancelLongPress();
      if (this._barOpenedByHold) { // the click that ended the hold
        this._barOpenedByHold = false;
        return;
      }
      this.react(this.myReaction || DEFAULT_REACTION);
    },
    // react sets the given emoji as the viewer's reaction, or removes it
    // when they already hold that one — a user has at most one reaction
    // per tweet, so switching is a single react call.
    async react(emoji) {
      const owner = warpnetService.getOwnerProfile();
      if (!owner) return;
      this.showReactionBar = false;

      const removing = this.myReaction === emoji;
      // Painted up front: on a bridged tweet this call waits on the gateway
      // handing the reaction to the author's instance, and a button that does
      // nothing for those seconds reads as broken.
      const previous = {
        emoji: this.myReaction,
        reactions: this.reactions,
        count: this.reactionsCount.get(this.tweet.id),
      };
      this.paintOwnReaction(removing ? "" : emoji);

      try {
        if (removing) {
          await warpnetService.unreactTweet(this.tweet.id, this.tweet.user_id)
        } else {
          await warpnetService.reactToTweet(this.tweet.id, this.tweet.user_id, emoji)
        }
      } catch (err) {
        console.error(`failed to react to tweet [${this.tweet.id}]`, err);
        toast.error(err?.message || "Couldn't update reaction. Please try again.");
        this.myReaction = previous.emoji;
        this.reactions = previous.reactions;
        this.reactionsCount.set(this.tweet.id, previous.count);
        await this.loadTweetStats(this.tweet.id, this.tweet.user_id);
        return;
      }
      if (removing) {
        await warpnetService.deleteReactor(this.tweet.id, owner.user_id)
      } else {
        await warpnetService.setReactor(this.tweet.id, owner.user_id, owner, emoji)
      }

      // The response carries this node's own tally, which on a bridged tweet
      // counts only our reaction; the real breakdown comes from the author's
      // node, the way retweet() refreshes.
      try {
        await this.loadTweetStats(this.tweet.id, this.tweet.user_id);
      } catch (err) {
        console.error(`failed to refresh tweet stats [${this.tweet.id}]`, err);
      }
    },
    // paintOwnReaction moves the viewer's own reaction to `emoji` ("" takes it
    // back) in the tally on screen, so the chips and the counter follow the
    // click instead of waiting for the network.
    paintOwnReaction(emoji) {
      const reactions = {...this.reactions};
      let count = this.reactionsCount.get(this.tweet.id) || 0;
      if (this.myReaction) {
        const left = (reactions[this.myReaction] || 1) - 1;
        if (left > 0) {
          reactions[this.myReaction] = left;
        } else {
          delete reactions[this.myReaction];
        }
        count = Math.max(0, count - 1);
      }
      if (emoji) {
        reactions[emoji] = (reactions[emoji] || 0) + 1;
        count += 1;
      }
      this.myReaction = emoji;
      this.reactions = reactions;
      this.reactionsCount.set(this.tweet.id, count);
    },
    getReactionsCount(tweetId) {
      return this.reactionsCount.get(tweetId);
    },
    getRetweetsCount(tweetId) {
      return this.retweetsCount.get(tweetId);
    },
    getRepliesCount(tweetId) {
      return this.repliesCount.get(tweetId);
    },
    getViewsCount(tweetId) {
      return this.viewsCount.get(tweetId) || 0;
    },
    async loadTweetStats(tweetId, userId) {
      const stats = await warpnetService.getTweetStats(tweetId, userId);
      if (!stats || !stats.tweet_id) {
        // Transient handler/stream error surfaces as an empty body; a
        // single delayed retry keeps the counters from silently showing
        // zeros until the next full reload.
        if (!this.statsRetried) {
          this.statsRetried = true;
          this._statsRetryTimer = setTimeout(() => {
            this._statsRetryTimer = null;
            this.loadTweetStats(tweetId, userId).catch(() => {});
          }, 2500);
        }
        return;
      }

      // my_reaction is answered from our own node, so it outranks the
      // local cache — it survives a browser reset and other devices. An
      // absent key means an older node that knows nothing of reactions;
      // there the cache stays in charge.
      if (stats.my_reaction !== undefined) {
        this._reactionAnswered = true;
        this.myReaction = stats.my_reaction || "";
      }
      // A bridged tweet's breakdown comes from the author's instance, which
      // hears of our reaction only once the gateway has delivered it. Keep
      // showing it until then instead of letting the answer take it away.
      const reactions = {...(stats.reactions || {})};
      let reactionsCount = stats.reactions_count || 0;
      if (this.myReaction && !reactions[this.myReaction]) {
        reactions[this.myReaction] = 1;
        reactionsCount += 1;
      }
      this.reactions = reactions;
      this.reactionsCount.set(stats.tweet_id, reactionsCount);
      this.retweetsCount.set(stats.tweet_id, stats.retweets_count);
      this.repliesCount.set(stats.tweet_id, stats.replies_count);
      // Views are monotonically non-decreasing: a stale read raced with
      // our own RecordView would otherwise clobber the higher value.
      const incoming = stats.views_count || 0;
      const current = this.viewsCount.get(stats.tweet_id) || 0;
      if (incoming > current) {
        this.viewsCount.set(stats.tweet_id, incoming);
      }
    },
    async recordView() {
      if (this.viewRecorded || this.viewInFlight) return;
      this.viewInFlight = true;
      try {
        const count = await warpnetService.viewTweet(this.tweet.id, this.tweet.user_id);
        // viewTweet returns `null` on any failure; only mark the view
        // recorded (and stop observing) when the backend confirms.
        if (count === null) return;
        // Monotonic: never regress a higher local count when a stale
        // loadTweetStats response lands after us.
        const current = this.viewsCount.get(this.tweet.id) || 0;
        if (count > current) {
          this.viewsCount.set(this.tweet.id, count);
        }
        this.viewRecorded = true;
        if (this.viewObserver) {
          this.viewObserver.disconnect();
          this.viewObserver = null;
        }
      } catch (err) {
        // Fail silently per spec - never break the page on a view miss.
        // Leave viewRecorded false so a later intersection retries.
        console.error(`failed to record view for tweet [${this.tweet.id}]`, err);
      } finally {
        this.viewInFlight = false;
      }
    },
    setupViewObserver() {
      if (typeof window === 'undefined' || typeof window.IntersectionObserver === 'undefined') {
        // Without IntersectionObserver fall back to recording immediately.
        this.recordView();
        return;
      }
      const target = this.$refs.tweetRoot;
      if (!target) return;

      // We want "the tweet is meaningfully on screen". Two signals
      // satisfy that:
      //   - at least half of the tweet itself is visible (short tweets), or
      //   - the visible slice of the tweet covers at least half of the
      //     viewport (tall tweets / multi-image — intersectionRatio
      //     against the tweet can never reach 0.5 when the tweet is
      //     more than 2× the viewport height).
      //
      // The observer callback only fires when intersectionRatio
      // crosses one of these thresholds, so the list must contain a
      // value at-or-below max(intersectionRatio) for any tweet we
      // expect to record. Compute a per-element low threshold from
      // the actual element/viewport heights so even a 200×-viewport-
      // tall tweet produces a callback at the fill-viewport point.
      const visibleFraction = 0.5;
      const targetHeight = target.getBoundingClientRect().height || 0;
      const viewportHeight = (typeof window !== 'undefined'
          && (window.innerHeight || (document && document.documentElement && document.documentElement.clientHeight)))
          || 0;
      const fillRatio = (targetHeight > 0 && viewportHeight > 0)
          ? (viewportHeight * visibleFraction) / targetHeight
          : 0;
      const thresholds = Array.from(new Set([
          0, 0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 0.75, 1,
          // For ultra-tall tweets the static list bottoms out at
          // 0.005; supplement with values around the actual fill
          // point so we never silently miss the crossing.
          ...(fillRatio > 0 && fillRatio < 0.005
              ? [Math.max(fillRatio / 2, 1e-6), fillRatio]
              : []),
      ])).filter(t => t >= 0 && t <= 1).sort((a, b) => a - b);
      this.viewObserver = new IntersectionObserver((entries) => {
        for (const entry of entries) {
          if (!entry.isIntersecting) continue;
          const root = entry.rootBounds;
          const fallbackHeight = (typeof window !== 'undefined' && window.innerHeight) || 0;
          const rootHeight = (root && root.height > 0) ? root.height : fallbackHeight;
          const fillsViewport = rootHeight > 0
              && (entry.intersectionRect.height / rootHeight) >= visibleFraction;
          if (entry.intersectionRatio >= visibleFraction || fillsViewport) {
            this.recordView();
            break;
          }
        }
      }, { threshold: thresholds });
      this.viewObserver.observe(target);
    },
  },
  async created() {
    console.log("loading component:", this.$options.name);
    console.log("loading tweet:", JSON.stringify(this.tweet));
    if (!this.tweet || !this.tweet.id || !this.tweet.user_id) {
      // Defensive: nothing to render against. Avoid firing
      // getProfile/getTweetStats with empty ids — the backend rejects
      // those and logs spurious errors.
      return;
    }
    const owner = warpnetService.getOwnerProfile();
    this.isOwner = owner && owner.user_id === this.tweet.user_id;

    // Every asset is an independent per-element fetch: the text and the
    // counters must never wait behind a hanging author node or blob, and
    // one failed element must not take its siblings down with it.
    this.loadAuthor();
    this.loadRetweeterLabel();
    this.loadImages();
    if (this.isLocked) {
      this.loadSponsoredContent()
          .catch(err => console.warn(`failed to load sponsored tweet [${this.tweet.id}]`, err));
    }
    if (this.tweet.video_key && this.autoloadVideo) {
      this.loadVideo();
    }

    this.loadTweetStats(this.tweet.id, this.tweet.user_id)
        .then(() => this.refreshInteractionState())
        .catch(err => console.error(`failed to load tweet stats [${this.tweet.id}]`, err));

    if (this.tweet.quoted_tweet_id) {
      this.loadQuotedSource();
    }
  },
  mounted() {
    this.$nextTick(() => this.setupViewObserver());
  },
  beforeUnmount() {
    if (this.viewObserver) {
      this.viewObserver.disconnect();
      this.viewObserver = null;
    }
    if (this._onLightboxKeyup) {
      window.removeEventListener("keyup", this._onLightboxKeyup);
      this._onLightboxKeyup = null;
    }
    if (this._statsRetryTimer) {
      clearTimeout(this._statsRetryTimer);
      this._statsRetryTimer = null;
    }
    if (this._unwatchOrder) {
      this._unwatchOrder();
      this._unwatchOrder = null;
    }
    this.cancelLongPress();
    this.cancelReactionBar();
    this.teardownOutsideClose();
  },
};
</script>
